using UnityEngine;

[CreateAssetMenu(menuName = "Cards/Card Data", fileName = "NewCardData")]
public class CardData : GameItemData
{
    // --------------------------------------------------
    // CARD INFO
    // --------------------------------------------------

    [Header("Card Info")]
    [Tooltip("Displayed text for the card's intention (e.g., 'Deal damage', 'Block', etc.).")]
    [TextArea(1, 3)]
    public string intentionText;

    [Tooltip("Sound cue played when this card is used.")]
    public SFXCueData soundCue;

    [Tooltip("Energy cost to play this card.")]
    public int energyCost;

    // --------------------------------------------------
    // ANIMATION SETTINGS
    // --------------------------------------------------

    [Header("Animation Settings")]
    [Tooltip("Animation played by the source entity when this card is used (e.g., Attack).")]
    public EnemyAnim sourceAnim = EnemyAnim.Attack;

    [Tooltip("Animation played by the target entity when this card is used (e.g., Hurt).")]
    public EnemyAnim targetAnim = EnemyAnim.Hurt;

    // --------------------------------------------------
    // VARIABILITY SETTINGS
    // --------------------------------------------------

    [Header("Variability Settings")]
    [Tooltip("If true, this card can roll variable potency (Poor, Normal, Potent) based on its multiplier range.")]
    public bool isVariableCard = false;

    [Tooltip("Artwork shown when the card rolls a Poor outcome (optional).")]
    public Sprite poorArtwork;

    [Tooltip("Artwork shown when the card rolls a Potent outcome (optional).")]
    public Sprite potentArtwork;

    [Header("Variability Threshold")]

    [Tooltip("The upper bound range of the variability threshold.")]
    [Range(0f, 1f)] public float maxMultiplierThreshold = 0.66f;

    [Tooltip("The lower bound range of the variability threshold.")]
    [Range(0f, 1f)] public float minMultiplierThreshold = 0.33f;

    // naming prefixes
    [Header("Name Prefixes")]
    public string weakPrefix = "Poor";
    public string strongPrefix = "Potent";

    [Tooltip("Color for weak prefix text.")]
    public Color weakPrefixColor = Color.gray;

    [Tooltip("Color for strong prefix text.")]
    public Color strongPrefixColor = new Color(1f, 0.4f, 0.4f);

    // --------------------------------------------------
    // VALIDATION HELPERS
    // --------------------------------------------------

    // checks if card variability is valid
    public bool IsCardVariabilityValid()
    {
        return isVariableCard && effects != null && effects.Count == 1;
    }

    // postcopy rolled effect
    public CardVariationTier GetVariationTier(Effect rolledEffect)
    {
        float min = rolledEffect.minMultiplier;
        float max = rolledEffect.maxMultiplier;
        float baseVal = rolledEffect.baseValue;
        float post = rolledEffect.postCopyValue;
        float lowBound = baseVal * min;
        float highBound = baseVal * max;

        if (post == baseVal) // for cases where there is no gap between minT, maxT and multiplier isn't on
            return CardVariationTier.NormalModifier;

        // Normalize
        float t = Mathf.InverseLerp(lowBound, highBound, post);

        if (t <= minMultiplierThreshold)
            return CardVariationTier.WeakModifier;
        if (t >= maxMultiplierThreshold)
            return CardVariationTier.StrongModifier;
        return CardVariationTier.NormalModifier; // ultimate fallback
    }
    public string GetWeakPrefixColorTag() =>
        ColorUtility.ToHtmlStringRGB(weakPrefixColor);

    public string GetStrongPrefixColorTag() =>
        ColorUtility.ToHtmlStringRGB(strongPrefixColor);

    public string GetColoredPrefix(CardVariationTier tier)
    {
        return tier switch
        {
            CardVariationTier.WeakModifier =>
                $"<color=#{GetWeakPrefixColorTag()}>{weakPrefix}</color>",
            CardVariationTier.StrongModifier =>
                $"<color=#{GetStrongPrefixColorTag()}>{strongPrefix}</color>",
            _ => string.Empty
        };
    }

    protected override void OnValidate()
    {

        base.OnValidate();

        // Ensure max ≥ min
        if (maxMultiplierThreshold < minMultiplierThreshold)
            maxMultiplierThreshold = minMultiplierThreshold;

        // Ensure min ≤ max
        if (minMultiplierThreshold > maxMultiplierThreshold)
            minMultiplierThreshold = maxMultiplierThreshold;

        // Optional: clamp inside 0–1 range (even though Range attribute does this in inspector)
        minMultiplierThreshold = Mathf.Clamp01(minMultiplierThreshold);
        maxMultiplierThreshold = Mathf.Clamp01(maxMultiplierThreshold);
    }
}

using UnityEngine;

[CreateAssetMenu(menuName = "Cards/Card Data", fileName = "NewCardData")]
public class CardData : GameItemData
{
    // --------------------------------------------------
    // CARD INFO
    // --------------------------------------------------

    [Header("Card Info")]
    [Tooltip("Displayed text for the card's intention (e.g., 'Deal damage', 'Block', etc.).")]
    [TextArea(1, 3)]
    public string intentionText;

    [Tooltip("Sound cue played when this card is used.")]
    public SFXCueData soundCue;

    [Tooltip("Energy cost to play this card.")]
    public int energyCost;

    // --------------------------------------------------
    // ANIMATION SETTINGS
    // --------------------------------------------------

    [Header("Animation Settings")]
    [Tooltip("Animation played by the source entity when this card is used (e.g., Attack).")]
    public EnemyAnim sourceAnim = EnemyAnim.Attack;

    [Tooltip("Animation played by the target entity when this card is used (e.g., Hurt).")]
    public EnemyAnim targetAnim = EnemyAnim.Hurt;

    // --------------------------------------------------
    // VARIABILITY SETTINGS
    // --------------------------------------------------

    [Header("Variability Settings")]
    [Tooltip("If true, this card can roll variable potency (Poor, Normal, Potent) based on its multiplier range.")]
    public bool isVariableCard = false;

    [Tooltip("Artwork shown when the card rolls a Poor outcome (optional).")]
    public Sprite poorArtwork;

    [Tooltip("Artwork shown when the card rolls a Potent outcome (optional).")]
    public Sprite potentArtwork;

    [Header("Variability Threshold")]

    [Tooltip("The upper bound range of the variability threshold.")]
    [Range(0f, 1f)] public float maxMultiplierThreshold = 0.66f;

    [Tooltip("The lower bound range of the variability threshold.")]
    [Range(0f, 1f)] public float minMultiplierThreshold = 0.33f;

    // naming prefixes
    [Header("Name Prefixes")]
    public string weakPrefix = "Poor";
    public string strongPrefix = "Potent";

    [Tooltip("Color for weak prefix text.")]
    public Color weakPrefixColor = Color.gray;

    [Tooltip("Color for strong prefix text.")]
    public Color strongPrefixColor = new Color(1f, 0.4f, 0.4f);

    // --------------------------------------------------
    // VALIDATION HELPERS
    // --------------------------------------------------

    // checks if card variability is valid
    public bool IsCardVariabilityValid()
    {
        return isVariableCard && effects != null && effects.Count == 1;
    }

    // postcopy rolled effect
    public CardVariationTier GetVariationTier(Effect rolledEffect)
    {
        float min = rolledEffect.minMultiplier;
        float max = rolledEffect.maxMultiplier;
        float baseVal = rolledEffect.baseValue;
        float post = rolledEffect.postCopyValue;
        float lowBound = baseVal * min;
        float highBound = baseVal * max;

        if (post == baseVal) // for cases where there is no gap between minT, maxT and multiplier isn't on
            return CardVariationTier.NormalModifier;

        // Normalize
        float t = Mathf.InverseLerp(lowBound, highBound, post);

        if (t <= minMultiplierThreshold)
            return CardVariationTier.WeakModifier;
        if (t >= maxMultiplierThreshold)
            return CardVariationTier.StrongModifier;
        return CardVariationTier.NormalModifier; // ultimate fallback
    }
    public string GetWeakPrefixColorTag() =>
        ColorUtility.ToHtmlStringRGB(weakPrefixColor);

    public string GetStrongPrefixColorTag() =>
        ColorUtility.ToHtmlStringRGB(strongPrefixColor);

    public string GetColoredPrefix(CardVariationTier tier)
    {
        return tier switch
        {
            CardVariationTier.WeakModifier =>
                $"<color=#{GetWeakPrefixColorTag()}>{weakPrefix}</color>",
            CardVariationTier.StrongModifier =>
                $"<color=#{GetStrongPrefixColorTag()}>{strongPrefix}</color>",
            _ => string.Empty
        };
    }

    /// <summary>
    /// Gets the appropriate artwork sprite based on the variation tier.
    /// Returns poorArtwork for weak tier, potentArtwork for strong tier, or default artwork otherwise.
    /// </summary>
    public Sprite GetArtworkForTier(CardVariationTier tier)
    {
        return tier switch
        {
            CardVariationTier.WeakModifier => poorArtwork != null ? poorArtwork : artwork,
            CardVariationTier.StrongModifier => potentArtwork != null ? potentArtwork : artwork,
            _ => artwork
        };
    }

    protected override void OnValidate()
    {

        base.OnValidate();

        // Ensure max ≥ min
        if (maxMultiplierThreshold < minMultiplierThreshold)
            maxMultiplierThreshold = minMultiplierThreshold;

        // Ensure min ≤ max
        if (minMultiplierThreshold > maxMultiplierThreshold)
            minMultiplierThreshold = maxMultiplierThreshold;

        // Optional: clamp inside 0–1 range (even though Range attribute does this in inspector)
        minMultiplierThreshold = Mathf.Clamp01(minMultiplierThreshold);
        maxMultiplierThreshold = Mathf.Clamp01(maxMultiplierThreshold);
    }
}

using System.Collections.Generic;
using GameItems;
using GameItems.Cards;
using GameItems.Cards.Helpers;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

// CardRender populates the UI for a single card instance using a prefab with the
// following expected hierarchy (names can be adjusted, but these are auto-detected):
// CardPrefab
//  └─ Wrapper
//      ├─ CardBackground (Image)
//      ├─ EnergyCost     (TMP_Text)
//      ├─ CardName       (TMP_Text)
//      ├─ CardIcon       (Image)
//      └─ DescriptionText(TMP_Text)
//
// You can either assign the fields in the inspector, or leave them null and CardRender
// will attempt to find them by name among the children (case-insensitive contains check).
public class CardRender : MonoBehaviour,
    IPointerEnterHandler,
    IPointerExitHandler,
    IPointerDownHandler,
    IBeginDragHandler,
    IDragHandler,
    IEndDragHandler
{
    [Header("UI References")] 
    [SerializeField] private SpriteRenderer cardBackground;
    [SerializeField] private SpriteRenderer cardIcon;
    [SerializeField] private TMP_Text energyCost;
    [SerializeField] private TMP_Text cardName;
    [SerializeField] private TMP_Text descriptionText;

    [Header("Defaults")] 
    [Tooltip("Shown when CardData does not specify an artwork.")]
    [SerializeField] private Sprite fallbackIcon;
    [Tooltip("Used if no energy value is provided when binding.")]
    [SerializeField] private int defaultEnergyCost = 1;

    [Header("Runtime")] 
    public CardData Data;
    public CardInstance Instance;

    private GameItems.Cards.Helpers.CardFXHelper _fxHelper;
    private bool _isDragging;

    private void Awake()
    {
        // Auto-wire references if not assigned
        if (cardBackground == null) cardBackground = FindChildByName<SpriteRenderer>("CardBackground");
        if (cardIcon == null) cardIcon = FindChildByName<SpriteRenderer>("CardIcon");
        if (energyCost == null) energyCost = FindChildByName<TMP_Text>("EnergyCost");
        if (cardName == null) cardName = FindChildByName<TMP_Text>("CardName");
        if (descriptionText == null) descriptionText = FindChildByName<TMP_Text>("DescriptionText");

        _fxHelper = GetComponent<GameItems.Cards.Helpers.CardFXHelper>();
        if (_fxHelper == null) _fxHelper = gameObject.AddComponent<GameItems.Cards.Helpers.CardFXHelper>();
    }

    public void Bind(CardData data)
    {
        Instance = null;
        Data = data;
        // Name/Description
        if (cardName != null) cardName.text = data != null ? data.name : string.Empty;
        if (descriptionText != null) descriptionText.text = data != null ? data.description : string.Empty;

        cardBackground.sprite = data != null ? data.artwork : null;
        cardIcon.sprite = data != null ? data.icon : null;

        // Energy
        int energyVal = data.energyCost;
        if (energyCost != null)
        {
            energyCost.text = energyVal > 0 ? energyVal.ToString() : string.Empty;
        }
    }

    public void Bind(CardInstance instance, int? energy = null)
    {
        Instance = instance;
        Data = instance != null ? instance.data : null;

        // Name with variability tier prefix if present
        if (cardName != null)
        {
            if (instance != null && instance.tier.HasValue && Data != null)
            {
                string prefix = Data.GetColoredPrefix(instance.tier.Value);
                cardName.text = string.IsNullOrEmpty(prefix) ? Data.name : $"{prefix} {Data.name}";
            }
            else
            {
                cardName.text = Data != null ? Data.name : string.Empty;
            }
        }

        // Description: keep base text; optionally append rolled summary for clarity
        if (descriptionText != null)
        {
            string baseDesc = Data != null ? Data.description : string.Empty;
            if (instance != null && instance.rolledEffects != null && instance.rolledEffects.Count > 0)
            {
                int dmg = instance.GetTotal(OperationType.Damage);
                int blk = instance.GetTotal(OperationType.AddShield);
                string summary = string.Empty;
                if (dmg != 0) summary += $" +{dmg} Damage";
                if (blk != 0) summary += (summary.Length > 0 ? "," : "") + $" +{blk} Block";
                if (!string.IsNullOrEmpty(summary)) baseDesc = $"{baseDesc}\n[{summary.Trim()}]";
            }
            descriptionText.text = baseDesc;
        }

        // Sprites from data
        cardBackground.sprite = Data != null ? Data.artwork : null;
        cardIcon.sprite = Data != null ? Data.icon : null;

        // Energy from CardData
        int energyVal = energy ?? (Data != null ? Data.energyCost : defaultEnergyCost);
        if (energyCost != null)
        {
            energyCost.text = energyVal > 0 ? energyVal.ToString() : string.Empty;
        }
    }

    // ─────────────────────────────────────────────
    // Pointer & Mouse listeners to drive CardFXHelper
    // ─────────────────────────────────────────────
    public void OnPointerEnter(PointerEventData eventData)
    {
        if (_fxHelper != null && !_isDragging)
        {
            _fxHelper.OnCardHover(this);
        }
    }

    public void OnPointerExit(PointerEventData eventData)
    {
        if (_fxHelper != null && !_isDragging)
        {
            _fxHelper.OnCardHoverExit(this);
        }
    }

    public void OnPointerDown(PointerEventData eventData)
    {
        if (_fxHelper != null)
        {
            _fxHelper.OnCardSelect(this);
        }
    }

    public void OnPointerUp(PointerEventData eventData)
    {
        // If we didn't drag (OnEndDrag not called), reset the card
        if (!_isDragging && _fxHelper != null)
        {
            // Simply exit hover - OnPointerEnter will handle re-hovering if needed
            _fxHelper.OnCardHoverExit(this);
        }
    }

    public void OnBeginDrag(PointerEventData eventData)
    {
        _isDragging = true;
        if (_fxHelper != null)
        {
            // Don't update original position - keep the one from OnPointerDown
            _fxHelper.OnCardSelect(this, updatePosition: false);
        }
    }

    public void OnDrag(PointerEventData eventData)
    {
        if (_fxHelper != null)
        {
            _fxHelper.OnCardDrag(this, eventData.position);
        }
    }

    public void OnEndDrag(PointerEventData eventData)
    {
        _isDragging = false;

        if (_fxHelper != null)
        {
            bool validTarget = false;
            TargetRule rule = Data.GetDominatingTargetRule();

            EnemyRender targetEnemy = null;

            switch (rule)
            {
                case TargetRule.Enemy:
                    targetEnemy = GetEnemyOnMouse(eventData.position);
                    if (targetEnemy != null)
                        validTarget = true;
                    break;

                case TargetRule.Self:
                    validTarget = true;
                    break;
            }

            if (validTarget)
            {
                var playerManager = FindFirstObjectByType<PlayerManager>();
                if (playerManager != null)
                {
                    bool cardPlayed = playerManager.PlayCard(Data, Instance, targetEnemy);
                    if (!cardPlayed)
                        validTarget = false;
                    else
                    {
                        var roundManager = FindFirstObjectByType<RoundManager>();
                        if (roundManager != null && roundManager.handViewer != null)
                            roundManager.handViewer.RebuildSmart();
                    }
                }
                else
                {
                    validTarget = false;
                }
            }

            _fxHelper.OnCardRelease(this, validTarget);

            // ALWAYS FIX LAYOUT AFTER DRAG
            var handViewer = FindFirstObjectByType<DeckViewer>();
            if (handViewer != null)
                handViewer.RebuildSmart();
        }
    }

    private EnemyRender GetEnemyOnMouse(Vector2 screenPosition)
    {
        // Convert screen position to world position
        Camera cam = Camera.main;
        if (cam == null)
        {
            Debug.LogWarning("[CardRender] Camera.main is null, cannot check enemy collision.");
            return null;
        }

        Vector3 worldPos = cam.ScreenToWorldPoint(new Vector3(screenPosition.x, screenPosition.y, cam.nearClipPlane));

        // Raycast at the drop position to check for enemy colliders, ignoring the card itself
        RaycastHit2D[] hits = new RaycastHit2D[10];
        ContactFilter2D filter = new ContactFilter2D();

        Physics2D.Raycast(worldPos, Vector2.zero, filter, hits);

        foreach (var hit in hits)
        {
            if (hit.collider == null) continue;

            // Skip if it's this card's collider
            if (hit.collider.gameObject == gameObject || hit.collider.transform.IsChildOf(transform))
                continue;

            Debug.Log($"Hit: {hit.collider.name}");

            // Check if the hit object has an EnemyRender component
            EnemyRender enemyRender = hit.collider.GetComponent<EnemyRender>();
            if (enemyRender != null && enemyRender.data is { isAlive: true })
            {
                Debug.Log($"[CardRender] Card dropped on enemy: {enemyRender.data.enemyName}");
                return enemyRender;
            }
        }

        return null;
    }

    // Optional support for non-UI hover via physics raycast (if collider present)
    private void OnMouseOver()
    {
        if (_fxHelper != null && !_isDragging)
        {
            _fxHelper.OnCardHover(this);
        }
    }

    private void OnMouseExit()
    {
        // No-op; exit visuals are handled elsewhere (e.g., release/cancel)
    }

    public void SetEnergy(int value)
    {
        if (energyCost != null) energyCost.text = value.ToString();
    }

    public void SetBackground(Sprite bg)
    {
        if (cardBackground == null) return;
        cardBackground.sprite = bg;
        cardBackground.enabled = bg != null;
    }

    public void SetIcon(Sprite sprite)
    {
        if (cardIcon == null) return;
        cardIcon.sprite = sprite;
        cardIcon.enabled = sprite != null;
    }

    private T FindChildByName<T>(string containsName) where T : Component
    {
        var comps = GetComponentsInChildren<T>(true);
        containsName = containsName.ToLowerInvariant();
        foreach (var c in comps)
        {
            if (c.name.ToLowerInvariant().Contains(containsName))
                return c;
        }
        return null;
    }
}

using System.Collections.Generic;
using GameItems;
using GameItems.Cards;
using GameItems.Cards.Helpers;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

// CardRender populates the UI for a single card instance using a prefab with the
// following expected hierarchy (names can be adjusted, but these are auto-detected):
// CardPrefab
//  └─ Wrapper
//      ├─ CardBackground (Image)
//      ├─ EnergyCost     (TMP_Text)
//      ├─ CardName       (TMP_Text)
//      ├─ CardIcon       (Image)
//      └─ DescriptionText(TMP_Text)
//
// You can either assign the fields in the inspector, or leave them null and CardRender
// will attempt to find them by name among the children (case-insensitive contains check).
public class CardRender : MonoBehaviour,
    IPointerEnterHandler,
    IPointerExitHandler,
    IPointerDownHandler,
    IBeginDragHandler,
    IDragHandler,
    IEndDragHandler
{
    [Header("UI References")] 
    [SerializeField] private SpriteRenderer cardBackground;
    [SerializeField] private SpriteRenderer cardIcon;
    [SerializeField] private TMP_Text energyCost;
    [SerializeField] private TMP_Text cardName;
    [SerializeField] private TMP_Text descriptionText;

    [Header("Defaults")] 
    [Tooltip("Shown when CardData does not specify an artwork.")]
    [SerializeField] private Sprite fallbackIcon;
    [Tooltip("Used if no energy value is provided when binding.")]
    [SerializeField] private int defaultEnergyCost = 1;

    [Header("Runtime")] 
    public CardData Data;
    public CardInstance Instance;

    private GameItems.Cards.Helpers.CardFXHelper _fxHelper;
    private bool _isDragging;

    private void Awake()
    {
        // Auto-wire references if not assigned
        if (cardBackground == null) cardBackground = FindChildByName<SpriteRenderer>("CardBackground");
        if (cardIcon == null) cardIcon = FindChildByName<SpriteRenderer>("CardIcon");
        if (energyCost == null) energyCost = FindChildByName<TMP_Text>("EnergyCost");
        if (cardName == null) cardName = FindChildByName<TMP_Text>("CardName");
        if (descriptionText == null) descriptionText = FindChildByName<TMP_Text>("DescriptionText");

        _fxHelper = GetComponent<GameItems.Cards.Helpers.CardFXHelper>();
        if (_fxHelper == null) _fxHelper = gameObject.AddComponent<GameItems.Cards.Helpers.CardFXHelper>();
    }

    public void Bind(CardData data)
    {
        Instance = null;
        Data = data;
        // Name/Description
        if (cardName != null) cardName.text = data != null ? data.name : string.Empty;
        if (descriptionText != null) descriptionText.text = data != null ? data.description : string.Empty;

        cardBackground.sprite = data != null ? data.artwork : null;
        cardIcon.sprite = data != null ? data.icon : null;

        // Energy
        int energyVal = data.energyCost;
        if (energyCost != null)
        {
            energyCost.text = energyVal > 0 ? energyVal.ToString() : string.Empty;
        }
    }

    public void Bind(CardInstance instance, int? energy = null)
    {
        Instance = instance;
        Data = instance != null ? instance.data : null;

        // Name with variability tier prefix if present
        if (cardName != null)
        {
            if (instance != null && instance.tier.HasValue && Data != null)
            {
                string prefix = Data.GetColoredPrefix(instance.tier.Value);
                cardName.text = string.IsNullOrEmpty(prefix) ? Data.name : $"{prefix} {Data.name}";
            }
            else
            {
                cardName.text = Data != null ? Data.name : string.Empty;
            }
        }

        // Description: keep base text; optionally append rolled summary for clarity
        if (descriptionText != null)
        {
            string baseDesc = Data != null ? Data.description : string.Empty;
            if (instance != null && instance.rolledEffects != null && instance.rolledEffects.Count > 0)
            {
                int dmg = instance.GetTotal(OperationType.Damage);
                int blk = instance.GetTotal(OperationType.AddShield);
                string summary = string.Empty;
                if (dmg != 0) summary += $" +{dmg} Damage";
                if (blk != 0) summary += (summary.Length > 0 ? "," : "") + $" +{blk} Block";
                if (!string.IsNullOrEmpty(summary)) baseDesc = $"{baseDesc}\n[{summary.Trim()}]";
            }
            descriptionText.text = baseDesc;
        }

        // Sprites from data - use tier-specific artwork if available
        if (Data != null)
        {
            if (instance != null && instance.tier.HasValue)
            {
                cardBackground.sprite = Data.GetArtworkForTier(instance.tier.Value);
            }
            else
            {
                cardBackground.sprite = Data.artwork;
            }
            cardIcon.sprite = Data.icon;
        }
        else
        {
            cardBackground.sprite = null;
            cardIcon.sprite = null;
        }

        // Energy from CardData
        int energyVal = energy ?? (Data != null ? Data.energyCost : defaultEnergyCost);
        if (energyCost != null)
        {
            energyCost.text = energyVal > 0 ? energyVal.ToString() : string.Empty;
        }
    }

    // ─────────────────────────────────────────────
    // Pointer & Mouse listeners to drive CardFXHelper
    // ─────────────────────────────────────────────
    public void OnPointerEnter(PointerEventData eventData)
    {
        if (_fxHelper != null && !_isDragging)
        {
            _fxHelper.OnCardHover(this);
        }
    }

    public void OnPointerExit(PointerEventData eventData)
    {
        if (_fxHelper != null && !_isDragging)
        {
            _fxHelper.OnCardHoverExit(this);
        }
    }

    public void OnPointerDown(PointerEventData eventData)
    {
        if (_fxHelper != null)
        {
            _fxHelper.OnCardSelect(this);
        }
    }

    public void OnPointerUp(PointerEventData eventData)
    {
        // If we didn't drag (OnEndDrag not called), reset the card
        if (!_isDragging && _fxHelper != null)
        {
            // Simply exit hover - OnPointerEnter will handle re-hovering if needed
            _fxHelper.OnCardHoverExit(this);
        }
    }

    public void OnBeginDrag(PointerEventData eventData)
    {
        _isDragging = true;
        if (_fxHelper != null)
        {
            // Don't update original position - keep the one from OnPointerDown
            _fxHelper.OnCardSelect(this, updatePosition: false);
        }
    }

    public void OnDrag(PointerEventData eventData)
    {
        if (_fxHelper != null)
        {
            _fxHelper.OnCardDrag(this, eventData.position);
        }
    }

    public void OnEndDrag(PointerEventData eventData)
    {
        _isDragging = false;

        if (_fxHelper != null)
        {
            bool validTarget = false;
            TargetRule rule = Data.GetDominatingTargetRule();

            EnemyRender targetEnemy = null;

            switch (rule)
            {
                case TargetRule.Enemy:
                    targetEnemy = GetEnemyOnMouse(eventData.position);
                    if (targetEnemy != null)
                        validTarget = true;
                    break;

                case TargetRule.Self:
                    validTarget = true;
                    break;
            }

            if (validTarget)
            {
                var playerManager = FindFirstObjectByType<PlayerManager>();
                if (playerManager != null)
                {
                    bool cardPlayed = playerManager.PlayCard(Data, Instance, targetEnemy);
                    if (!cardPlayed)
                        validTarget = false;
                    else
                    {
                        var roundManager = FindFirstObjectByType<RoundManager>();
                        if (roundManager != null && roundManager.handViewer != null)
                            roundManager.handViewer.RebuildSmart();
                    }
                }
                else
                {
                    validTarget = false;
                }
            }

            _fxHelper.OnCardRelease(this, validTarget);

            // ALWAYS FIX LAYOUT AFTER DRAG
            var handViewer = FindFirstObjectByType<DeckViewer>();
            if (handViewer != null)
                handViewer.RebuildSmart();
        }
    }

    private EnemyRender GetEnemyOnMouse(Vector2 screenPosition)
    {
        // Convert screen position to world position
        Camera cam = Camera.main;
        if (cam == null)
        {
            Debug.LogWarning("[CardRender] Camera.main is null, cannot check enemy collision.");
            return null;
        }

        Vector3 worldPos = cam.ScreenToWorldPoint(new Vector3(screenPosition.x, screenPosition.y, cam.nearClipPlane));

        // Raycast at the drop position to check for enemy colliders, ignoring the card itself
        RaycastHit2D[] hits = new RaycastHit2D[10];
        ContactFilter2D filter = new ContactFilter2D();

        Physics2D.Raycast(worldPos, Vector2.zero, filter, hits);

        foreach (var hit in hits)
        {
            if (hit.collider == null) continue;

            // Skip if it's this card's collider
            if (hit.collider.gameObject == gameObject || hit.collider.transform.IsChildOf(transform))
                continue;

            Debug.Log($"Hit: {hit.collider.name}");

            // Check if the hit object has an EnemyRender component
            EnemyRender enemyRender = hit.collider.GetComponent<EnemyRender>();
            if (enemyRender != null && enemyRender.data is { isAlive: true })
            {
                Debug.Log($"[CardRender] Card dropped on enemy: {enemyRender.data.enemyName}");
                return enemyRender;
            }
        }

        return null;
    }

    // Optional support for non-UI hover via physics raycast (if collider present)
    private void OnMouseOver()
    {
        if (_fxHelper != null && !_isDragging)
        {
            _fxHelper.OnCardHover(this);
        }
    }

    private void OnMouseExit()
    {
        // No-op; exit visuals are handled elsewhere (e.g., release/cancel)
    }

    public void SetEnergy(int value)
    {
        if (energyCost != null) energyCost.text = value.ToString();
    }

    public void SetBackground(Sprite bg)
    {
        if (cardBackground == null) return;
        cardBackground.sprite = bg;
        cardBackground.enabled = bg != null;
    }

    public void SetIcon(Sprite sprite)
    {
        if (cardIcon == null) return;
        cardIcon.sprite = sprite;
        cardIcon.enabled = sprite != null;
    }

    private T FindChildByName<T>(string containsName) where T : Component
    {
        var comps = GetComponentsInChildren<T>(true);
        containsName = containsName.ToLowerInvariant();
        foreach (var c in comps)
        {
            if (c.name.ToLowerInvariant().Contains(containsName))
                return c;
        }
        return null;
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace GameItems
{
    /// <summary>
    /// Displays the turn timer UI with a countdown and optional visual feedback.
    /// </summary>
    public class TurnTimerUI : MonoBehaviour
    {
        [Header("References")]
        [Tooltip("Reference to the RoundManager to read timer values")]
        public RoundManager roundManager;

        [Header("UI Elements")]
        [Tooltip("Text component to display the remaining time")]
        public TextMeshProUGUI timerText;

        [Tooltip("Optional fill image to show timer visually")]
        public Image timerFillImage;

        [Header("Visual Settings")]
        [Tooltip("Color when time is plentiful")]
        public Color normalColor = Color.white;

        [Tooltip("Color when time is running low")]
        public Color warningColor = Color.yellow;

        [Tooltip("Color when time is almost out")]
        public Color criticalColor = Color.red;

        [Tooltip("Time threshold for warning color (seconds)")]
        public float warningThreshold = 7f;

        [Tooltip("Time threshold for critical color (seconds)")]
        public float criticalThreshold = 3f;

        private void Start()
        {
            // Auto-find RoundManager if not assigned
            if (roundManager == null)
            {
                roundManager = FindFirstObjectByType<RoundManager>();
            }

            if (roundManager == null)
            {
                Debug.LogError("TurnTimerUI: RoundManager not found!");
                enabled = false;
            }
        }

        private void Update()
        {
            if (roundManager == null || !roundManager.playerTurn || !roundManager.battleActive)
            {
                // Hide timer when not player's turn
                if (timerText != null) timerText.text = "";
                if (timerFillImage != null) timerFillImage.fillAmount = 0f;
                return;
            }

            float timeRemaining = roundManager.currentTurnTime;
            float timeLimit = roundManager.turnTimeLimit;

            // Update text
            if (timerText != null)
            {
                timerText.text = $"{Mathf.CeilToInt(timeRemaining)}s";

                // Update color based on time remaining
                if (timeRemaining <= criticalThreshold)
                {
                    timerText.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerText.color = warningColor;
                }
                else
                {
                    timerText.color = normalColor;
                }
            }

            // Update fill image
            if (timerFillImage != null && timeLimit > 0)
            {
                timerFillImage.fillAmount = timeRemaining / timeLimit;

                // Update fill color
                if (timeRemaining <= criticalThreshold)
                {
                    timerFillImage.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerFillImage.color = warningColor;
                }
                else
                {
                    timerFillImage.color = normalColor;
                }
            }
        }
    }
}
